    /// <param name="businessConnectionId">Unique identifier of the business connection on behalf of which the link will be created. For payments in Telegram Stars only.</param>
    /// <param name="providerToken">Payment provider token, obtained via @BotFather. Pass an empty string for payments in Telegram Stars.</param>
    /// <param name="subscriptionPeriod">The number of seconds the subscription will be active for before the next payment. The currency must be set to "XTR" (Telegram Stars) if the parameter is used. Currently, it must always be 2592000 (30 days) if specified. Any number of subscriptions can be active for a given bot at the same time, including multiple concurrent subscriptions from the same user. Subscription price must no exceed 10000 Telegram Stars.</param>
    /// <param name="maxTipAmount">The maximum accepted amount for tips in the smallest units of the currency (integer, not float/double). For example, for a maximum tip of US$ 1.45 pass max_tip_amount = 145. See the exp parameter in currencies.json, it shows the number of digits past the decimal point for each currency (2 for the majority of currencies). Defaults to 0. Not supported for payments in Telegram Stars.</param>
    /// <param name="suggestedTipAmounts">A JSON-serialized Array of suggested amounts of tips in the smallest units of the currency (integer, not float/double). At most 4 suggested tip amounts can be specified. The suggested tip amounts must be positive, passed in a strictly increased order and must not exceed max_tip_amount.</param>
    /// <param name="providerData">JSON-serialized data about the invoice, which will be shared with the payment provider. A detailed description of required fields should be provided by the payment provider.</param>
    /// <param name="photoUrl">URL of the product photo for the invoice. Can be a photo of the goods or a marketing image for a service.</param>
    /// <param name="photoSize">Photo size in bytes</param>
    /// <param name="photoWidth">Photo width</param>
    /// <param name="photoHeight">Photo height</param>
    /// <param name="needName">Pass True if you require the user's full name to complete the order. Ignored for payments in Telegram Stars.</param>
    /// <param name="needPhoneNumber">Pass True if you require the user's phone number to complete the order. Ignored for payments in Telegram Stars.</param>
    /// <param name="needEmail">Pass True if you require the user's email address to complete the order. Ignored for payments in Telegram Stars.</param>
    /// <param name="needShippingAddress">Pass True if you require the user's shipping address to complete the order. Ignored for payments in Telegram Stars.</param>
    /// <param name="sendPhoneNumberToProvider">Pass True if the user's phone number should be sent to the provider. Ignored for payments in Telegram Stars.</param>
    /// <param name="sendEmailToProvider">Pass True if the user's email address should be sent to the provider. Ignored for payments in Telegram Stars.</param>
    /// <param name="isFlexible">Pass True if the final price depends on the shipping method. Ignored for payments in Telegram Stars.</param>
    /// <remarks><see href="https://core.telegram.org/bots/api#createinvoicelink"/></remarks>
    Task<string> CreateInvoiceLinkAsync(string title, string description, string payload, string currency, IReadOnlyList<Api.LabeledPrice> prices, string? businessConnectionId = null, string? providerToken = null, long? subscriptionPeriod = null, long? maxTipAmount = null, IReadOnlyList<long>? suggestedTipAmounts = null, string? providerData = null, string? photoUrl = null, long? photoSize = null, long? photoWidth = null, long? photoHeight = null, bool? needName = null, bool? needPhoneNumber = null, bool? needEmail = null, bool? needShippingAddress = null, bool? sendPhoneNumberToProvider = null, bool? sendEmailToProvider = null, bool? isFlexible = null, CancellationToken cancellationToken = default);

    /// <summary>
    ///     If you sent an invoice requesting a shipping address and the parameter is_flexible was specified, the Bot API will send an Update with a shipping_query field to the bot. Use this method to reply to shipping queries. On success, True is returned.
    /// </summary>
    /// <param name="shippingQueryId">Unique identifier for the query to be answered</param>
    /// <param name="ok">Pass True if delivery to the specified address is possible and False if there are any problems (for example, if delivery to the specified address is not possible)</param>
    /// <param name="shippingOptions">Required if ok is True. A JSON-serialized Array of available shipping options.</param>
    /// <param name="errorMessage">Required if ok is False. Error message in human readable form that explains why it is impossible to complete the order (e.g. "Sorry, delivery to your desired address is unavailable"). Telegram will display this message to the user.</param>
    /// <remarks><see href="https://core.telegram.org/bots/api#answershippingquery"/></remarks>
    Task<bool> AnswerShippingQueryAsync(string shippingQueryId, bool ok, IReadOnlyList<Api.ShippingOption>? shippingOptions = null, string? errorMessage = null, CancellationToken cancellationToken = default);

    /// <summary>
    ///     Once the user has confirmed their payment and shipping details, the Bot API sends the final confirmation in the form of an Update with the field pre_checkout_query. Use this method to respond to such pre-checkout queries. On success, True is returned. Note: The Bot API must receive an answer within 10 seconds after the pre-checkout query was sent.
    /// </summary>
    /// <param name="preCheckoutQueryId">Unique identifier for the query to be answered</param>
    /// <param name="ok">Specify True if everything is alright (goods are available, etc.) and the bot is ready to proceed with the order. Use False if there are any problems.</param>
    /// <param name="errorMessage">Required if ok is False. Error message in human readable form that explains the reason for failure to proceed with the checkout (e.g. "Sorry, somebody just bought the last of our amazing black T-shirts while you were busy filling out your payment details. Please choose a different color or garment!"). Telegram will display this message to the user.</param>
    /// <remarks><see href="https://core.telegram.org/bots/api#answerprecheckoutquery"/></remarks>
    Task<bool> AnswerPreCheckoutQueryAsync(string preCheckoutQueryId, bool ok, string? errorMessage = null, CancellationToken cancellationToken = default);

    /// <summary>
    ///     A method to get the current Telegram Stars balance of the bot. Requires no parameters. On success, returns a StarAmount object.
    /// </summary>
    /// <remarks><see href="https://core.telegram.org/bots/api#getmystarbalance"/></remarks>
    Task<Api.StarAmount> GetMyStarBalanceAsync(CancellationToken cancellationToken = default);

    /// <summary>
    ///     Returns the bot's Telegram Star transactions in chronological order. On success, returns a StarTransactions object.
    /// </summary>
    /// <param name="offset">Number of transactions to skip in the response</param>
    /// <param name="limit">The maximum number of transactions to be retrieved. Values between 1-100 are accepted. Defaults to 100.</param>
    /// <remarks><see href="https://core.telegram.org/bots/api#getstartransactions"/></remarks>
    Task<Api.StarTransactions> GetStarTransactionsAsync(long? offset = null, long? limit = null, CancellationToken cancellationToken = default);

    /// <summary>
    ///     Refunds a successful payment in Telegram Stars. Returns True on success.
    /// </summary>
    /// <param name="userId">Identifier of the user whose payment will be refunded</param>
    /// <param name="telegramPaymentChargeId">Telegram payment identifier</param>
    /// <remarks><see href="https://core.telegram.org/bots/api#refundstarpayment"/></remarks>
    Task<bool> RefundStarPaymentAsync(long userId, string telegramPaymentChargeId, CancellationToken cancellationToken = default);

    /// <summary>
    ///     Allows the bot to cancel or re-enable extension of a subscription paid in Telegram Stars. Returns True on success.
    /// </summary>
    /// <param name="userId">Identifier of the user whose subscription will be edited</param>
    /// <param name="telegramPaymentChargeId">Telegram payment identifier for the subscription</param>
    /// <param name="isCanceled">Pass True to cancel extension of the user subscription; the subscription must be active up to the end of the current subscription period. Pass False to allow the user to re-enable a subscription that was previously canceled by the bot.</param>
    /// <remarks><see href="https://core.telegram.org/bots/api#edituserstarsubscription"/></remarks>
    Task<bool> EditUserStarSubscriptionAsync(long userId, string telegramPaymentChargeId, bool isCanceled, CancellationToken cancellationToken = default);

    /// <summary>
    ///     Informs a user that some of the Telegram Passport elements they provided contains errors. The user will not be able to re-submit their Passport to you until the errors are fixed (the contents of the field for which you returned the error must change). Returns True on success.<br/>
    ///     Use this if the data submitted by the user doesn't satisfy the standards your service requires for any reason. For example, if a birthday date seems invalid, a submitted document is blurry, a scan shows evidence of tampering, etc. Supply some details in the error message to make sure the user knows how to correct the issues.
    /// </summary>
    /// <param name="userId">User identifier</param>
    /// <param name="errors">A JSON-serialized Array describing the errors</param>
    /// <remarks><see href="https://core.telegram.org/bots/api#setpassportdataerrors"/></remarks>
    Task<bool> SetPassportDataErrorsAsync(long userId, IReadOnlyList<Api.PassportElementError> errors, CancellationToken cancellationToken = default);

    /// <summary>
    ///     Use this method to send a game. On success, the sent Message is returned.
    /// </summary>
    /// <param name="chatId">Unique identifier for the target chat or username of the target bot in the format @username. Games can't be sent to channel direct messages chats and channel chats.</param>
    /// <param name="gameShortName">Short name of the game, serves as the unique identifier for the game. Set up your games via @BotFather.</param>
    /// <param name="businessConnectionId">Unique identifier of the business connection on behalf of which the message will be sent</param>
    /// <param name="messageThreadId">Unique identifier for the target message thread (topic) of a forum; for forum supergroups and private chats of bots with forum topic mode enabled only</param>
    /// <param name="disableNotification">Sends the message silently. Users will receive a notification with no sound.</param>
    /// <param name="protectContent">Protects the contents of the sent message from forwarding and saving</param>
    /// <param name="allowPaidBroadcast">Pass True to allow up to 1000 messages per second, ignoring broadcasting limits for a fee of 0.1 Telegram Stars per message. The relevant Stars will be withdrawn from the bot's balance.</param>
    /// <param name="messageEffectId">Unique identifier of the message effect to be added to the message; for private chats only</param>
    /// <param name="replyParameters">Description of the message to reply to</param>
    /// <param name="replyMarkup">A JSON-serialized object for an inline keyboard. If empty, one 'Play game_title' button will be shown. If not empty, the first button must launch the game.</param>
    /// <remarks><see href="https://core.telegram.org/bots/api#sendgame"/></remarks>
    Task<Api.Message> SendGameAsync(Api.ChatId chatId, string gameShortName, string? businessConnectionId = null, long? messageThreadId = null, bool? disableNotification = null, bool? protectContent = null, bool? allowPaidBroadcast = null, string? messageEffectId = null, Api.ReplyParameters? replyParameters = null, Api.InlineKeyboardMarkup? replyMarkup = null, CancellationToken cancellationToken = default);

    /// <summary>
    ///     Use this method to set the score of the specified user in a game message. On success, if the message is not an inline message, the Message is returned, otherwise True is returned. Returns an error, if the new score is not greater than the user's current score in the chat and force is False.
    /// </summary>
    /// <param name="userId">User identifier</param>
    /// <param name="score">New score, must be non-negative</param>
    /// <param name="force">Pass True if the high score is allowed to decrease. This can be useful when fixing mistakes or banning cheaters.</param>
    /// <param name="disableEditMessage">Pass True if the game message should not be automatically edited to include the current scoreboard</param>
    /// <param name="chatId">Required if inline_message_id is not specified. Unique identifier for the target chat.</param>
    /// <param name="messageId">Required if inline_message_id is not specified. Identifier of the sent message.</param>
    /// <param name="inlineMessageId">Required if chat_id and message_id are not specified. Identifier of the inline message.</param>
    /// <remarks><see href="https://core.telegram.org/bots/api#setgamescore"/></remarks>
    Task<Api.Message?> SetGameScoreAsync(long userId, long score, bool? force = null, bool? disableEditMessage = null, long? chatId = null, long? messageId = null, string? inlineMessageId = null, CancellationToken cancellationToken = default);

    /// <summary>
    ///     Use this method to get data for high score tables. Will return the score of the specified user and several of their neighbors in a game. Returns an Array of GameHighScore objects.
    /// </summary>
    /// <param name="userId">Target user id</param>
    /// <param name="chatId">Required if inline_message_id is not specified. Unique identifier for the target chat.</param>
    /// <param name="messageId">Required if inline_message_id is not specified. Identifier of the sent message.</param>
    /// <param name="inlineMessageId">Required if chat_id and message_id are not specified. Identifier of the inline message.</param>
    /// <remarks><see href="https://core.telegram.org/bots/api#getgamehighscores"/></remarks>
    Task<IReadOnlyList<Api.GameHighScore>> GetGameHighScoresAsync(long userId, long? chatId = null, long? messageId = null, string? inlineMessageId = null, CancellationToken cancellationToken = default);

}

